def digest(data):
    return hashlib.sha256(data).hexdigest()

def checked(path, record):
    raw=Path(path).read_bytes()
    if len(raw)!=record['bytes'] or digest(raw)!=record['sha256']:
        raise ValueError('Changed complete source: '+str(path))
    return raw.decode('utf-8')

def apply(text, operations, reverse=False):
    for item in (reversed(operations) if reverse else operations):
        before,after=(item['new'],item['old']) if reverse else (item['old'],item['new'])
        if text.count(before)!=item['count']:
            raise ValueError('Exact full-source patch count differs')
        text=text.replace(before,after)
    return text

def reproduce(repo, outdir, *, verify_existing=False):
    repo=Path(repo).resolve();outdir=Path(outdir).resolve()
    if outdir==repo or repo in outdir.parents:
        raise ValueError('Reproduce complete sources into separate scratch, then publish the reviewed originals')
    results={}
    for item in SPEC:
        parent=checked(repo/item['parent']['path'],item['parent'])
        actual=apply(parent,item['operations'])
        encoded=actual.encode('utf-8')
        expected=item['output']
        if len(encoded)>=100000 or len(encoded)!=expected['bytes'] or digest(encoded)!=expected['sha256']:
            raise ValueError('Complete output differs: '+expected['name'])
        if apply(actual,item['operations'],reverse=True)!=parent:
            raise ValueError('Complete inverse replay differs: '+expected['name'])
        target=outdir/expected['name']
        if verify_existing:
            checked(target,expected)
        else:
            outdir.mkdir(parents=True,exist_ok=True)
            if target.exists() and target.read_bytes()!=encoded:
                raise ValueError('Do not overwrite a different whole source: '+str(target))
            target.write_bytes(encoded)
        results[expected['name']]=dict(bytes=len(encoded),sha256=digest(encoded))
    return results

def main():
    p=argparse.ArgumentParser(description=__doc__)
    p.add_argument('--repo',type=Path,required=True)
    p.add_argument('--outdir',type=Path,required=True)
    p.add_argument('--verify-existing',action='store_true')
    a=p.parse_args()
    result=reproduce(a.repo,a.outdir,verify_existing=a.verify_existing)
    print(json.dumps(dict(complete=True,source_only=True,scientific_import_or_execution=False,
        whole_forward_and_inverse_replay=True,outputs=result),sort_keys=True))

if __name__=='__main__':
    main()
